import torch
import torch.distributed as dist
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _split_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    chunks = torch.chunk(x, ws, dim=-1)
    return chunks[_rank()].contiguous()


def _gather_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous().clone()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad)


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x)

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: take local slice of last dim. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _gather_last_dim(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: take local slice."""

    @staticmethod
    def forward(ctx, x):
        return _gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last_dim(grad)


def _divide(a, b):
    assert a % b == 0, f"{a} is not divisible by {b}"
    return a // b


def _make_master(master_weight, out_features, in_features):
    if master_weight is None:
        master_weight = torch.empty(out_features, in_features)
        torch.nn.init.xavier_normal_(master_weight)
    master_weight = master_weight.detach()
    assert tuple(master_weight.shape) == (out_features, in_features), (
        f"master_weight shape {tuple(master_weight.shape)} != "
        f"{(out_features, in_features)}"
    )
    return master_weight


class ColumnParallelLinear(torch.nn.Module):
    """Y = XA + b with A split along its output (column) dimension.

    Weight is stored as (out_features // world_size, in_features), like nn.Linear.
    Output partitions are all-gathered along the last dimension.
    """

    def __init__(self, in_features, out_features, bias=True, master_weight=None):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.output_size_per_partition = _divide(out_features, self.world_size)

        master_weight = _make_master(master_weight, out_features, in_features)
        start = self.rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        self.weight = torch.nn.Parameter(master_weight[start:end, :].clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(out)


class RowParallelLinear(torch.nn.Module):
    """Y = XA + b with A split along its input (row) dimension.

    Weight is stored as (out_features, in_features // world_size), like nn.Linear.
    Partial outputs are all-reduced (summed); bias is full on each rank and
    added after the reduction.
    """

    def __init__(self, in_features, out_features, bias=True, master_weight=None):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.input_size_per_partition = _divide(in_features, self.world_size)

        master_weight = _make_master(master_weight, out_features, in_features)
        start = self.rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        self.weight = torch.nn.Parameter(master_weight[:, start:end].clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input or an already-partitioned input.
        if x.shape[-1] == self.in_features and self.world_size > 1:
            x = _ScatterToParallelRegion.apply(x)
        elif x.shape[-1] != self.input_size_per_partition:
            raise ValueError(
                f"Expected last dim {self.in_features} or "
                f"{self.input_size_per_partition}, got {x.shape[-1]}"
            )
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
